sp_widget.client_script:
api.controller=function($scope) {
  /* widget controller */
  var c = this;

	// Estado inicial (pode ser null, true ou false)
$scope.isLowercase = null;

// Escuta evento do rootScope para atualizar o estado
$scope.$root.$on('toggleCaseEvent', function(event, isLowercase) {
  $scope.isLowercase = isLowercase;
});

};

sp_widget.css:
.servicos-widget {
  font-family: 'Roboto Flex', sans-serif !important;
  font-weight: 600;
  display: flex;
  align-items: center;
  justify-content: center;
  max-width: 80%;
  margin: 25px auto 2rem auto; /* centraliza horizontalmente e adiciona margem superior */
  position: static;
  text-align: center; /* garante que o texto também fique centralizado */
}

.servicos-text {
  font-family: 'Roboto Flex', sans-serif !important;
  font-size: 3.4rem;
  color: #2F2F2F;
  padding: 10px;
}
.lowercase-text {
  text-transform: lowercase;
}

.uppercase-text {
  text-transform: uppercase;
}


/* Responsivo */
@media (max-width: 900px) {
  .servicos-widget {
    max-width: 90%;
  }
}
